INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('2g5758zex1ke4ykmcci9f2g575zfkhrq', '2026-Q3', 'Set/2026 (T3)', '2026-09-18T04:53'::timestamptz, 'Daniela Patriani Antonio', 'daniela patriani antonio', 'PHARUS', 'Cleuber Anicesio', 8.0, 'Neutro', 9.0, NULL, NULL, NULL, NULL, NULL, 'Desacreditei do método', 'Tenho clareza e estou executando com consistência', 'Frustada com a espera/demora para participar da “fabrica de recebiveis..” de geracao de renda passiva recorrente a 1,5% am, e tbem por esta txa ser menor que a de 1,6% am que eu tinha investido 5 cotas de 50 no ano passado com voces, em incorporação e me foi dito que esse investimento a 1,6 foi descontinuado.. decepcionante!!', 'Voltar a me disponibilizar o investimento de renda passiva recorrente a 1,6% am e devolver os 5.000,00 que paguei para participar do leilao serial, por favor, flexibilizando as regras do contrato assinado ref ao leilao.', NULL, 'Voltar a me disponibilizar o investimento que gera renda passiva recorrente a 1,6 am e devolver os 5.000,00 da entrada no leilao serial, flexibilizando as regras do contrato do leilao, uma vez que nem foi iniciado ainda. Obrigada', 'Me identifico totalmente com a linha de crescimento patrimonial de vices, baseado em imoveis, e demais ativos reais e renda fixa, mas na pratica esta deixando a desejar.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '2g5758zex1ke4ykmcci9f2g575zfkhrq', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_